def simulate_queue(operations):
    print("Starting queue simulation...")
    queue = []
    print(f"Initial queue state: {queue}")

    for op_type, item in operations:
        print(f"Processing operation: {op_type}, Item: {item}")
        if op_type == 'enqueue':
            queue.append(item)
            print(f"Enqueued '{item}'. Current queue: {queue}")
        elif op_type == 'dequeue':
            if queue:
                dequeued_item = queue.pop(0)
                print(f"Dequeued '{dequeued_item}'. Current queue: {queue}")
            else:
                print("Dequeue attempted on empty queue. No item removed.")
        else:
            print(f"Unknown operation type: '{op_type}'. Skipping.")
        print(f"Queue after operation: {queue}")

    print("All operations processed.")
    print(f"Final queue state before return: {queue}")
    return queue

