def is_leap_year(year):
    print(f"Checking if {year} is a leap year...")
    if (year % 4) == 0:
        print(f"{year} is divisible by 4.")
        if (year % 100) == 0:
            print(f"{year} is also divisible by 100.")
            if (year % 400) == 0:
                print(f"{year} is also divisible by 400. It's a leap year.")
                return True
            else:
                print(f"{year} is not divisible by 400. It's not a leap year.")
                return False
        else:
            print(f"{year} is not divisible by 100. It's a leap year.")
            return True
    else:
        print(f"{year} is not divisible by 4. It's not a leap year.")
        return False

print("Testing with various years:")
print(f"Result for 2000: {is_leap_year(2000)}")
print(f"Result for 1900: {is_leap_year(1900)}")
